items = json.loads(SRC)
for it in items:
    it['window'] = WIN
    for k in ('track', 'category', 'title', 'summary', 'source', 'source_url',
              'sentiment', 'score', 'direction', 'volatility', 'brief', 'window'):
        if k not in it:
            raise SystemExit(f'⚠️ 缺字段 {k} in {it["title"][:30]}')

# §3.114a 枚举硬守卫
bad_t = {x['track'] for x in items} - VALID_TRACK
bad_c = {x['category'] for x in items} - VALID_CAT
bad_d = {x['direction'] for x in items} - VALID_DIR
if bad_t or bad_c or bad_d:
    raise SystemExit(f'⚠️ 非法枚举值 track={bad_t} category={bad_c} direction={bad_d} → 会静默跳过回填与加权，终止')

json.dump(items, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print(f'✅ 写入 {OUT}：{len(items)} 条')
print('track 分布:', dict(Counter(x['track'] for x in items)))
print('sentiment 分布:', dict(Counter(x['sentiment'] for x in items)))
print('direction 分布:', dict(Counter(x['direction'] for x in items)))
print('source_url 覆盖:', sum(1 for x in items if x.get('source_url')), '/', len(items))
print('均值强度:', round(sum(x['score'] for x in items) / len(items), 2))
